srcDoc.css:
html, body {
  height: 100%;
  margin: 0;
  padding: 0;
  font-family: Arial, sans-serif;
  background-color: #ffffff;
  overflow: hidden;
}

body {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  padding: 10px;
}

#chat-container {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-right: 5px;
}

.message-box {
  padding: 10px 14px;
  border-radius: 6px;
  max-width: 85%;
  line-height: 1.4;
  font-size: 13px;
  box-sizing: border-box;
  word-break: break-word;
}

.user {
  background-color: #f7fafc;
  border-left: 4px solid #cbd5e0;
  align-self: flex-end;
}

.model {
  background-color: #ebf8ff;
  border-left: 4px solid #3182ce;
  align-self: flex-start;
}

.sender-title {
  font-size: 11px;
  margin: 0 0 4px 0;
  font-weight: bold;
}

.message-text {
  margin: 0;
}

.empty-state {
  text-align: center;
  color: #888;
  font-style: italic;
  margin-top: 30px;
  font-size: 13px;
}

srcDoc.js:
window.appsmith.onModelChange = model => {
  const container = document.getElementById('chat-container');
  if (!container) return;
  const messages = model.messages || [];
  if (messages.length === 0) {
    container.innerHTML = '<div class="empty-state">Noch keine Nachrichten vorhanden. Starte den Chat...</div>';
    return;
  }
  container.innerHTML = messages.map(msg => {
    const isUser = msg.role === 'user';
    const sender = isUser ? 'Du:' : 'Gemini:';
    const senderColor = isUser ? '#333' : '#2b6cb0';
    const cssClass = isUser ? 'user' : 'model';
    const safeText = (msg.text || '').replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, '<br>');
    return `
      <div class="message-box ${cssClass}">
        <div class="sender-title" style="color: ${senderColor};">${sender}</div>
        <div class="message-text">${safeText}</div>
      </div>
    `;
  }).join('');

  // Automatisch ganz nach unten scrollen
  container.scrollTop = container.scrollHeight;
};

